script:
frappe.ui.form.on("Driver", {
	refresh(frm) {
		if (frm.is_new()) {
			return;
		}

		if (!frm.doc.is_blacklisted) {
			frm.add_custom_button(__("Blacklist Driver"), () => {
				frappe.prompt(
					{ fieldname: "reason", fieldtype: "Small Text", label: __("Reason"), reqd: 1 },
					(values) => {
						frappe.call({
							method: "transport.transport.doctype.driver_incident.driver_incident.set_driver_blacklist",
							args: { driver: frm.doc.name, blacklisted: 1, reason: values.reason },
							callback: () => frm.reload_doc(),
						});
					},
					__("Blacklist Driver")
				);
			}, __("Transport"));
		} else {
			frm.add_custom_button(__("Clear Blacklist"), () => {
				frappe.call({
					method: "transport.transport.doctype.driver_incident.driver_incident.set_driver_blacklist",
					args: { driver: frm.doc.name, blacklisted: 0 },
					callback: () => frm.reload_doc(),
				});
			}, __("Transport"));
		}
	},
});

frappe.ui.form.on("Sales Invoice", {
	refresh(frm) {
		if (frm.is_new() || !frm.doc.transport_timesheet) {
			return;
		}

		if (frm.doc.grn_status === "Pending") {
			frm.add_custom_button(__("Mark GRN Received"), () => {
				frappe.call({
					method: "transport.transport.billing.mark_grn_received",
					args: { sales_invoice: frm.doc.name },
					callback: () => frm.reload_doc(),
				});
			}, __("Transport"));
		}

		if (frm.doc.grn_status === "Received" && frm.doc.invoice_submission_status === "Not Submitted") {
			frm.add_custom_button(__("Mark Invoice Submitted"), () => {
				frappe.call({
					method: "transport.transport.billing.mark_invoice_submitted",
					args: { sales_invoice: frm.doc.name },
					callback: () => frm.reload_doc(),
				});
			}, __("Transport"));
		}

		if (frm.doc.certificate_of_completion) {
			frm.add_custom_button(__("Certificate of Completion"), () => {
				frappe.set_route("Form", "Certificate of Completion", frm.doc.certificate_of_completion);
			}, __("Transport"));
		}
	},
});

frappe.listview_settings['Rental Vehicle'] = {
	onload(listview) {
		listview.page.add_actions_menu_item(__('Fetch Fines'), () => {
			const vehicles = listview.get_checked_items(true);
			if (!vehicles.length) {
				frappe.msgprint(__('Select at least one vehicle.'));
				return;
			}

			frappe.confirm(
				__('Fetch traffic fines for {0} selected vehicle(s)?', [vehicles.length]),
				() => {
					frappe.dom.freeze(__('Fetching fines...'));
					frappe.call({
						method: 'transport.transport.fine_sync.service.fetch_fines_for_vehicles',
						args: { vehicles: vehicles },
					}).then((r) => {
						frappe.dom.unfreeze();
						if (!r.message) return;
						const d = r.message;

						let html = `<p>${__('Vehicles selected')}: <b>${d.vehicles}</b><br>
							${__('Fines staged for review')}: <b>${d.fines_staged}</b></p>`;

						html += d.portals_queried.length
							? `<p>${__('Queried')}: ${d.portals_queried.map(frappe.utils.escape_html).join(', ')}</p>`
							: `<p>${__('No portal could be queried automatically.')}</p>`;

						// Coverage is stated plainly: a partial fetch must never
						// read as a complete picture of what a vehicle owes.
						if (d.coverage_note) {
							html += `<div class="alert alert-warning" style="margin-top:8px">
								<b>${__('Not a complete picture')}</b><br>${d.coverage_note}</div>`;
						}

						if (d.pending_operator && d.pending_operator.length) {
							html += `<p style="margin-top:8px"><b>${__('Still needs a person')}:</b></p><ul>`;
							d.pending_operator.forEach((p) => {
								html += `<li>${frappe.utils.escape_html(p.portal)}<br>
									<span class="text-muted small">${frappe.utils.escape_html((p.reason || '').slice(0, 220))}</span></li>`;
							});
							html += '</ul>';
						}

						if (d.fines_staged) {
							html += `<p style="margin-top:8px">
								<a href="/app/traffic-fine-staging?status=New">${__('Review staged fines')}</a></p>`;
						}

						frappe.msgprint({
							title: __('Fetch Fines'),
							indicator: d.police_fines_covered ? 'green' : 'orange',
							message: html,
						});
					}).catch(() => frappe.dom.unfreeze());
				}
			);
		});
	},
};

// Customers send the shuttle schedule as a seven-row table in which only the
// passenger count actually changes - times, pick-up points and the drop-off
// repeat in every row. Typing that seven times is the real friction, so the
// whole week is entered once here and expanded into rows.
//
// Enquiries commonly arrive with a time written TBA. That is recorded with the
// TBA tick rather than a made-up time, which keeps a schedule nobody has
// settled yet from reading like one that has been.

const DAYS = [
	"Monday",
	"Tuesday",
	"Wednesday",
	"Thursday",
	"Friday",
	"Saturday",
	"Sunday",
];
const WEEKEND = ["Saturday", "Sunday"];
// ISO weekday numbers, so a datetime entered once can be moved onto the right
// date for each day of that same week.
const DAY_ISO = {
	Monday: 1,
	Tuesday: 2,
	Wednesday: 3,
	Thursday: 4,
	Friday: 5,
	Saturday: 6,
	Sunday: 7,
};

frappe.ui.form.on("Opportunity", {
	refresh(frm) {
		frm.add_custom_button(
			__("Fill Week"),
			() => show_fill_week_dialog(frm),
			__("Transport")
		);
	},
});

function show_fill_week_dialog(frm) {
	const dialog = new frappe.ui.Dialog({
		title: __("Fill a Week of Shuttle Schedule"),
		fields: [
			{
				fieldname: "days",
				label: __("Days"),
				fieldtype: "MultiSelectList",
				reqd: 1,
				default: DAYS,
				get_data: () => DAYS.map((d) => ({ value: d, description: "" })),
			},
			{ fieldname: "sb_1", fieldtype: "Section Break" },
			{
				fieldname: "pickup_time",
				label: __("Pick-up Time"),
				fieldtype: "Datetime",
				description: __(
					"Enter it once against any date in the week. Each day gets the same time on its own date."
				),
			},
			{
				fieldname: "pickup_time_tba",
				label: __("Pick-up Time TBA"),
				fieldtype: "Check",
				description: __("Tick this when the customer wrote TBA rather than a time."),
			},
			{ fieldname: "cb_1", fieldtype: "Column Break" },
			{
				fieldname: "dropoff_time",
				label: __("Drop-off Time"),
				fieldtype: "Datetime",
			},
			{
				fieldname: "dropoff_time_tba",
				label: __("Drop-off Time TBA"),
				fieldtype: "Check",
			},
			{ fieldname: "sb_2", fieldtype: "Section Break" },
			{
				fieldname: "weekday_pax",
				label: __("No. of Pax (Mon-Fri)"),
				fieldtype: "Int",
			},
			{ fieldname: "cb_2", fieldtype: "Column Break" },
			{
				fieldname: "weekend_pax",
				label: __("No. of Pax (Sat-Sun)"),
				fieldtype: "Int",
				description: __("Weekend counts are usually lower. Leave blank to reuse the weekday count."),
			},
			{ fieldname: "sb_3", fieldtype: "Section Break" },
			{
				fieldname: "pickup_points",
				label: __("Pick-up Point Location"),
				fieldtype: "Small Text",
				reqd: 1,
				description: __("One location per line."),
			},
			{ fieldname: "cb_3", fieldtype: "Column Break" },
			{
				fieldname: "dropoff_location",
				label: __("Drop-off Point Location"),
				fieldtype: "Data",
			},
		],
		primary_action_label: __("Add Rows"),
		primary_action(values) {
			const added = fill_week(frm, values);
			dialog.hide();

			if (!added.length) {
				frappe.msgprint({
					title: __("Nothing Added"),
					message: __("Every day selected is already in the table."),
					indicator: "orange",
				});
				return;
			}

			frappe.show_alert({
				message: __("Added {0} day(s).", [added.length]),
				indicator: "green",
			});
		},
	});

	dialog.show();
}

// Keep the time of day, move the date onto the requested weekday of that same
// week - otherwise every row would carry whichever date happened to be picked.
function shift_to_weekday(value, day) {
	if (!value) {
		return null;
	}
	return moment(value).isoWeekday(DAY_ISO[day]).format("YYYY-MM-DD HH:mm:ss");
}

function fill_week(frm, values) {
	// Server-side validation rejects the same day twice, so skip what is
	// already there rather than letting the save fail afterwards.
	const existing = new Set(
		(frm.doc.transport_enquiry_schedule || []).map((row) => row.day)
	);

	const added = [];

	DAYS.filter((day) => (values.days || []).includes(day))
		.filter((day) => !existing.has(day))
		.forEach((day) => {
			const is_weekend = WEEKEND.includes(day);
			const pax =
				is_weekend && values.weekend_pax ? values.weekend_pax : values.weekday_pax;

			const row = frm.add_child("transport_enquiry_schedule", {
				day: day,
				// A time marked TBA is left empty rather than invented; the
				// server clears it on save too, so the two cannot disagree.
				pickup_time: values.pickup_time_tba
					? null
					: shift_to_weekday(values.pickup_time, day),
				pickup_time_tba: values.pickup_time_tba ? 1 : 0,
				dropoff_time: values.dropoff_time_tba
					? null
					: shift_to_weekday(values.dropoff_time, day),
				dropoff_time_tba: values.dropoff_time_tba ? 1 : 0,
				no_of_pax: pax,
				pickup_points: values.pickup_points,
				dropoff_location: values.dropoff_location,
			});
			added.push(row);
		});

	frm.refresh_field("transport_enquiry_schedule");
	return added;
}

// This is the whole ERPNext-side footprint of the browser extension, which is
// not part of the app and lives in apps/transport/extension. It adds one
// button, hands the request to the extension, and shows what comes back. It
// never talks to a portal itself - a desk page cannot, and this is not the file
// to try it in.

frappe.ui.form.on("Traffic Fine Portal", {
	refresh(frm) {
		if (frm.is_new()) return;
		// Enabled portals only. NOT gated on fetch_mode = "Operator Assisted",
		// which was the first shape and excluded the one portal this exists for:
		// TAMM is marked "Automated", and it is exactly the portal the server
		// cannot reliably read on its own - the CAPTCHA rate on the server's
		// address is why the extension was written. fetch_mode answers "should
		// this run unattended", which is a different question from "can a person
		// read it in their own browser".
		//
		// Portals the extension has no reader for are refused by the server, by
		// name, when the button is pressed: ingest_client_fetch and
		// get_client_fetch_target both throw "has no client fetch path". A
		// readable refusal on click beats a button that silently never appears.
		if (!frm.doc.is_enabled) return;

		frm.add_custom_button(__("Fetch Fines In This Browser"), () => start_fetch(frm));

		// The bridge announces itself as soon as it loads, which can be before
		// this script has a listener registered. Asking as well as listening
		// means a working install is never reported as a missing one just
		// because the two loaded in the wrong order.
		window.postMessage(
			{ source: BRIDGE_FROM_PAGE, kind: "PING", requestId: "ping" },
			window.location.origin
		);
	},
});

const BRIDGE_FROM_PAGE = "transport-fine-fetch/page";
const BRIDGE_FROM_EXTENSION = "transport-fine-fetch/extension";

// Set by the extension's bridge as soon as the desk loads. Absent means the
// extension is not installed, not enabled, or not permitted on this origin.
let bridge_version = null;

window.addEventListener("message", (event) => {
	if (event.source !== window || event.origin !== window.location.origin) return;
	const data = event.data;
	if (!data || data.source !== BRIDGE_FROM_EXTENSION) return;
	if (data.kind === "READY" || data.kind === "PONG") bridge_version = data.version;
});

function start_fetch(frm) {
	if (!bridge_version) {
		frappe.msgprint({
			title: __("Fine Fetch extension not found"),
			indicator: "orange",
			message: __(
				"This browser does not have the Fine Fetch extension enabled, so there is " +
					"nothing here that can open the portal. Install it, then reload this page."
			),
		});
		return;
	}

	const request_id = frappe.utils.get_random(12);

	const dialog = new frappe.ui.Dialog({
		title: __("Fetching fines"),
		fields: [{ fieldtype: "HTML", fieldname: "status" }],
		// No primary action: the operator's next step is in the portal tab, not
		// in this dialog. Closing it does not stop the fetch.
		secondary_action_label: __("Hide"),
		secondary_action: () => dialog.hide(),
	});

	const say = (message, indicator) => {
		dialog.fields_dict.status.$wrapper.html(
			`<div class="text-muted" style="padding:4px 0 8px">
				<span class="indicator ${indicator || "blue"}">${frappe.utils.escape_html(message)}</span>
			</div>`
		);
	};

	say(__("Opening the fines page…"));
	dialog.show();

	const on_message = (event) => {
		if (event.source !== window || event.origin !== window.location.origin) return;
		const data = event.data;
		if (!data || data.source !== BRIDGE_FROM_EXTENSION) return;
		if (data.requestId !== request_id) return;

		if (data.kind === "PROGRESS") {
			say(data.message);
			return;
		}

		if (data.kind !== "DONE") return;
		window.removeEventListener("message", on_message);

		if (!data.ok) {
			say(data.message, "red");
			return;
		}

		// A partial read is reported as its own outcome rather than folded into
		// a success: fines beyond the point it stopped were never seen, and
		// their absence here does not mean they do not exist.
		say(data.message, data.truncated ? "orange" : "green");
		frappe.show_alert({ message: data.message, indicator: data.truncated ? "orange" : "green" });
		frm.reload_doc();
	};

	window.addEventListener("message", on_message);

	window.postMessage(
		{
			source: BRIDGE_FROM_PAGE,
			kind: "FETCH",
			requestId: request_id,
			portal: frm.doc.name,
			// Sent so the extension can post results back as this user. The
			// traffic file number is deliberately not here - the extension asks
			// the server for it, so it never passes through this page.
			csrfToken: frappe.csrf_token,
		},
		window.location.origin
	);
}
